  // ══════════════════════════════════════════════════════════
  // Unit 5 · Node 2 · 어떻게 될까요?
  // A/V-(으)ㄹ까요?
  //
  // p.88 연습 1
  //
  // [보기]
  // A: 내일 날씨가 좋을까요?
  // B: 글쎄요, 저도 일기 예보를 안 봐서 모르겠어요.
  //
  // 1)
  // 저 식당 음식 / 맛있다
  // → 저 식당 음식이 맛있을까요?
  //
  // 2)
  // 시험 / 어렵다
  // → 시험이 어려울까요?
  //
  // 3)
  // 이 옷 / 맞다
  // → 유진 씨한테 이 옷이 맞을까요?
  //
  // 4)
  // 매운 음식 / 좋아하다
  // → 히엔 씨가 매운 음식을 좋아할까요?
  //
  // 5)
  // 이 책 / 읽을 수 있다
  // → 나나 씨가 이 책을 읽을 수 있을까요?
  //
  // p.89 연습 2
  //
  // [보기]
  // A: 민수 씨가 올까요?
  // B: 네, 지금 오고 있어요.
  //    아까 민수 씨한테서 전화가 왔어요.
  //
  // 1) 지금 길이 복잡하다
  // 2) 제주도에 가는 비행기 표가 싸다
  // 3) 아키라 씨가 지금 어디에 있다
  // 4) 이 영화가 재미있다
  // 5) 지금 가면 늦다
  // 6) 이번 주 일요일에 박물관 문을 열다
  //
  // Grammar 전용 타입 사용 금지.
  // ══════════════════════════════════════════════════════════

