  // ══════════════════════════════════════════════════════════
  // Unit 5 · Node 3 · A/V-(으)ㄹ 거예요
  //
  // p.90 연습 1
  //
  // [보기]
  // A: 내일도 추울까요?
  // B: 네, 아마 추울 거예요. 따뜻한 옷을 입고 오세요.
  //
  // 1)
  // A: 지금 강남역에 가려고 하는데 길이 막힐까요?
  // B: 네, 아마 길이 막힐 거예요. 지하철을 타세요.
  //
  // 2)
  // A: 이 책을 읽어 보고 싶은데 많이 어려울까요?
  // B: 네, 아마 많이 어려울 거예요. 좀 더 쉬운 책을 찾아보세요.
  //
  // 3)
  // A: 유진 씨 생일 선물로 이 옷을 샀는데 유진 씨가 좋아할까요?
  // B: 네, 아마 좋아할 거예요. 유진 씨가 좋아하는 스타일이에요.
  //
  // 4)
  // A: 줄리아 씨가 아키라 씨 전화번호를 알까요?
  // B: 네, 아마 알 거예요. 두 사람이 친해요.
  //
