  // ──────────────────────────────────────────────────────────
  // Lesson 2 · 이유를 말하고 행동해요
  //
  // p.92 연습 2 전체
  //
  // [보기]
  // 길이 복잡하다 + 지하철을 타다
  // → 길이 복잡하니까 지하철을 타세요.
  //
  // 1) 지금 시간이 없다 + 내일 다시 오다
  // → 지금 시간이 없으니까 내일 다시 오세요.
  //
  // 2) 담배는 건강에 안 좋다 + 피우지 말다
  // → 담배는 건강에 안 좋으니까 피우지 마세요.
  //
  // 3) 날씨가 너무 춥다 + 밖에 나가지 말다
  // → 날씨가 너무 추우니까 밖에 나가지 마세요.
  //
  // 4) 학생은 무료이다 + 그냥 들어가다
  // → 학생은 무료이니까 그냥 들어가세요.
  //
  // 5) 어제 많이 일했다 + 오늘은 쉬다
  // → 어제 많이 일했으니까 오늘은 쉬세요.
  //
  // 6) 늦었다 + 빨리 출발하다
  // → 늦었으니까 빨리 출발하세요.
  // ──────────────────────────────────────────────────────────

